resource "aws_iam_user" "web_manager" {
  name = "web_manager-${var.cgid}"
}

resource "aws_iam_access_key" "web_manager_key" {
  user = aws_iam_user.web_manager.name
}

resource "aws_iam_user_policy" "web_manager_s3_policy" {
  name = "WebManagerS3Policy-${var.cgid}"
  user = aws_iam_user.web_manager.name

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid: "IAMReadAccess",
        Effect: "Allow",
        Action: [
          "iam:List*",
          "iam:Get*"
        ],
        Resource: "*"
      },
      {
        Sid: "S3ReadOnly",
        Effect: "Allow",
        Action: [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:ListBucketVersions",
          "s3:GetObjectRetention"
        ],
        Resource: "arn:aws:s3:::cg-s3-version-index-*"
      },
      {
        Sid: "DenyPutObjectOnBypassBucket",
        Effect: "Deny",
        Action: "s3:PutObject",
        Resource: "arn:aws:s3:::cg-s3-version-index-*/*"
      }
    ]
  })
}

resource "aws_iam_user_policy" "web_manager_role_policy" {
  name = "WebManagerRoleControlPolicy-${var.cgid}"
  user = aws_iam_user.web_manager.name

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid: "CloudFormationAccess",
        Effect: "Allow",
        Action: [
          "cloudformation:CreateStack",
          "cloudformation:DescribeStacks",
          "cloudformation:DescribeStackEvents",
          "cloudformation:DeleteStack"
        ],
        Resource = "arn:aws:cloudformation:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:stack/*/*"
      },
      {
        Sid: "LambdaInvokeAllow",
        Effect: "Allow",
        Action: "lambda:InvokeFunction",
        Resource: "arn:aws:lambda:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:function:*"
      },
      {
        Sid: "AllowUseOfCFExecutionRole",
        Effect: "Allow",
        Action: [
          "iam:PassRole",
          "iam:GetRole"
        ],
        Resource: "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/CloudFormationRole-${var.cgid}"
      },
      {
        Sid: "AllowPassLambdaExecutionRole",
        Effect: "Allow",
        Action: [
          "iam:PassRole",
          "iam:GetRole"
        ],
        Condition: {
          "ForAnyValue:StringEquals" = {
            "aws:CalledVia" = "cloudformation.amazonaws.com"
          }
        },
        Resource: "arn:aws:iam::${data.aws_region.current.id}:role/LambdaPutObjectRole-${var.cgid}"
      }
    ]
  })
}

resource "aws_iam_role" "cloudformation_role" {
  name = "CloudFormationRole-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "cloudformation.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudformation_role_policy" {
  name = "CloudFormationInlinePolicy-${var.cgid}"
  role = aws_iam_role.cloudformation_role.name

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Action = [
          "lambda:CreateFunction",
          "lambda:GetFunction",
          "lambda:DeleteFunction",
          "iam:PassRole"
        ],
        Resource = "*"
      },
      {
        Effect = "Allow",
        Action = "iam:PassRole",
        Resource = "arn:aws:iam::912894834267:role/LambdaPutObjectRole-${var.cgid}",
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "lambda.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "lambda_putobject_role" {
  name = "LambdaPutObjectRole-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "lambda.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_putobject_policy" {
  name = "LambdaPutObjectPolicy-${var.cgid}"
  role = aws_iam_role.lambda_putobject_role.name

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Action = [
          "s3:PutObject"
        ],
        Resource = "arn:aws:s3:::cg-s3-version-index-*/*"
      }
    ]
  })
}

output "profile" {
  value = var.profile
}

output "cgid" {
  value = var.cgid
}

output "access_key_id" {
  value     = aws_iam_access_key.web_manager_key.id
}

output "secret_access_key" {
  value     = aws_iam_access_key.web_manager_key.secret
  sensitive = true
}

output "website_url" {
  value       = "http://${aws_s3_bucket.index_bucket.bucket}.s3-website-${var.region}.amazonaws.com"
  description = "URL of the static website"
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.6"
    }

    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.74.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack_name
      Scenario = var.scenario_name
    }
  }
}

resource "aws_s3_bucket" "flag_bucket" {
  bucket = "cg-s3-version-flag-${var.cgid}"
  tags = {
    Purpose = "Flag Only"
  }
}

resource "aws_s3_bucket_public_access_block" "flag_block" {
  bucket = aws_s3_bucket.flag_bucket.id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_object" "flag_txt" {
  bucket       = aws_s3_bucket.flag_bucket.id
  key          = "flag.txt"
  content      = "Flag{version_bypass_s3_only}"
  content_type = "text/plain"

  depends_on = [
    aws_s3_bucket.flag_bucket,
    aws_s3_bucket_public_access_block.flag_block
  ]
}

resource "aws_s3_bucket_policy" "flag_bucket_policy" {
  bucket = aws_s3_bucket.flag_bucket.id

  depends_on = [aws_s3_bucket_public_access_block.flag_block]

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid: "AllowOnlyFromReferer",
        Effect: "Allow",
        Principal: "*",
        Action: "s3:GetObject",
        Resource: "${aws_s3_bucket.flag_bucket.arn}/flag.txt",
        Condition: {
          StringLike: {
            "aws:Referer": "http://${aws_s3_bucket.index_bucket.bucket}.s3-website-${var.region}.amazonaws.com/*"
          }
        }
      },
      {
        Sid: "DenyWithoutReferer",
        Effect: "Deny",
        Principal: "*",
        Action: "s3:GetObject",
        Resource: "${aws_s3_bucket.flag_bucket.arn}/flag.txt",
        Condition: {
          Null: {
            "aws:Referer": "true"
          }
        }
      },
      {
        Sid: "DenyFromIAMUsers",
        Effect: "Deny",
        Principal: "*",
        Action: "s3:GetObject",
        Resource: "${aws_s3_bucket.flag_bucket.arn}/flag.txt",
        Condition: {
          StringLike: {
            "aws:PrincipalArn": "arn:aws:iam::*:user/*"
          }
        }
      },
      {
        Sid: "DenyFromAssumedRoles",
        Effect: "Deny",
        Principal: "*",
        Action: "s3:GetObject",
        Resource: "${aws_s3_bucket.flag_bucket.arn}/flag.txt",
        Condition: {
          StringEquals: {
            "aws:PrincipalType": "AssumedRole"
          }
        }
      },
      {
        Sid: "DenyFromAuthenticatedUsers",
        Effect: "Deny",
        Principal: {
          AWS: "*"
        },
        Action: "s3:GetObject",
        Resource: "${aws_s3_bucket.flag_bucket.arn}/flag.txt",
        Condition: {
          Bool: {
            "aws:PrincipalIsAWSService": "false"
          },
          StringNotEquals: {
            "aws:userid": "anonymous"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_cors_configuration" "flag_cors" {
  bucket = aws_s3_bucket.flag_bucket.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET"]
    allowed_origins = ["http://${aws_s3_bucket.index_bucket.bucket}.s3-website-${var.region}.amazonaws.com"]
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket" "index_bucket" {
  bucket = "cg-s3-version-index-${var.cgid}"
  object_lock_enabled = true
  tags = {
    Purpose = "Public Index"
  }
}

resource "aws_s3_bucket_public_access_block" "index_block" {
  bucket = aws_s3_bucket.index_bucket.id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_website_configuration" "index_website" {
  bucket = aws_s3_bucket.index_bucket.id

  index_document {
    suffix = "index.html"
  }
}

resource "aws_s3_bucket_versioning" "versioning" {
  bucket = aws_s3_bucket.index_bucket.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }

  depends_on = [aws_s3_bucket.index_bucket]
}

resource "aws_s3_bucket_policy" "index_bucket_policy" {
  bucket = aws_s3_bucket.index_bucket.id

  depends_on = [aws_s3_bucket_public_access_block.index_block]

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid: "PublicReadForIndex",
        Effect: "Allow",
        Principal: "*",
        Action: "s3:GetObject",
        Resource: "${aws_s3_bucket.index_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_s3_object" "index_admin" {
  bucket       = aws_s3_bucket.index_bucket.id
  key          = "index.html"
  content_type = "text/html"
  content      = <<EOT
<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"><title>S3 Flag Viewer</title></head>
<body style="background:#111;color:#0f0;text-align:center;padding-top:100px;font-family:monospace">
  <h1>🔓 S3 Flag Viewer</h1>
  <div id="flag">Loading flag...</div>
  <script>
    fetch("https://${aws_s3_bucket.flag_bucket.bucket}.s3.amazonaws.com/flag.txt")
    .then(r => r.text()).then(t => {
      document.getElementById("flag").innerHTML = "✅ FLAG: " + t;
    }).catch(e => {
      document.getElementById("flag").innerHTML = "❌ Failed to load flag";
    });
  </script>
</body>
</html>
EOT

  depends_on = [aws_s3_bucket_versioning.versioning]
}

resource "aws_s3_object" "index_normal" {
  bucket       = aws_s3_bucket.index_bucket.id
  key          = "index.html"
  content_type = "text/html"
  content      = "<h1>Welcome to our site</h1>"

  object_lock_mode               = "GOVERNANCE"
  object_lock_retain_until_date = "2099-12-31T00:00:00Z"

  depends_on = [
    aws_s3_object.index_admin,
    aws_s3_bucket_versioning.versioning
  ]
}

variable "profile" {
  description = "The AWS profile to use."
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources to."
  default     = "us-east-1"
  type        = string
}

variable "cgid" {
  description = "CloudGoat unique identifier."
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address(es)"
  type        = list(string)
}

variable "stack_name" {
  description = "Name of the stack."
  default     = "CloudGoat"
  type        = string
}

variable "scenario_name" {
  description = "Name of the scenario."
  default     = "s3_version_rollback_via_cfn"
  type        = string
}
